#!/usr/bin/env node
// build-bundle.js — the lesson's scripts as one minified file, which is what the page loads.
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');
const crypto = require('node:crypto');

const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, 'src', 'lesson.min.js');
const MAP = OUT + '.map.json';
const PAGE = path.join(ROOT, 'index.html');
const CHECK = process.argv.includes('--check');
const WATCH = process.argv.includes('--watch');

/* The dependency order: each script reads the ones above it. */
const ORDER = [
  'src/core/locales.js',
  'src/core/i18n.js',
  // the loading bar: its list (generated by tools/build-preload.js) and its loader
  'src/core/preload-list.js',
  'src/core/preload.js',
  'src/audio/sfx.js',
  'src/audio/vo.js',
  // the tune under the lesson: synthesised on the music bus, no files
  'src/audio/music.js',
  'src/fx/juice.js',
  'src/fx/snowflake.js',
  'src/fx/titlefx.js',
  'src/fx/transition.js',
  'src/core/input.js',
  'src/core/polygon-math.js',
  'src/core/director.js',
  'src/game/dialogue-timing.js',
  'src/game/screens.js',
  'src/character/swiftee-frames.js',
  'src/character/measuring-frames.js',
  'src/character/angle-measuring-frames.js',
  'src/character/sleigh-frames.js',
  'src/fx/sleigh-intro.js',
  'src/character/swiftee.js',
  // generated from the card kit in assets/source by tools/build-card.js
  'src/game/card-frame.js',
  'src/game/instruction.js',
  // generated from the button kit in assets/source by tools/build-buttons.js
  'src/game/button-frame.js',
  'src/game/hand-art.js',
  'src/game/stage.js',
  'src/game/dual-coding.js',
  'src/game/quest.js',
  'src/opening/swiftee-visit.js',
  'src/opening/runner-stage.js',
  'src/game/game.js'
];

const BANNER = '/* generated by tools/build-bundle.js from the sources in src/ — do not edit; the sources are the lesson */';

function esbuild() {
  try { return require('esbuild'); }
  catch (e) {
    console.error('esbuild is not installed: run  npm install  in part1-swiftee-lesson, then again');
    process.exit(1);
  }
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function vlq(n) {
  let v = n < 0 ? ((-n) << 1) | 1 : n << 1, s = '';
  do { let d = v & 31; v >>>= 5; if (v) d |= 32; s += B64[d]; } while (v);
  return s;
}
function joined() {
  const sources = [], contents = [], parts = [], lines = [];
  let prevSrc = 0, prevLine = 0;
  ORDER.forEach((rel, i) => {
    const text = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const part = text.endsWith('\n') ? text : text + '\n';   // the next file starts on a line of its own
    sources.push(rel.replace(/^src\//, ''));                 // the map lives in src/
    contents.push(text);
    parts.push(part);
    const n = part.split('\n').length - 1;
    for (let j = 0; j < n; j++) {
      lines.push(vlq(0) + vlq(i - prevSrc) + vlq(j - prevLine) + vlq(0));
      prevSrc = i; prevLine = j;
    }
  });
  const map = { version: 3, sources, sourcesContent: contents, names: [], mappings: lines.join(';') };
  return parts.join('') + '//# sourceMappingURL=data:application/json;base64,' + Buffer.from(JSON.stringify(map)).toString('base64') + '\n';
}

function build() {
  const es = esbuild();
  const r = es.transformSync(joined(), {
    loader: 'js',
    sourcefile: 'lesson.js',
    sourcemap: 'external',
    minify: true,
    target: 'es2017',
    charset: 'utf8',
    legalComments: 'none',
    banner: BANNER,
    logLevel: 'silent'
  });
  (r.warnings || []).forEach((w) => console.error('esbuild: ' + w.text));
  const code = r.code.replace(/\s*$/, '\n') + '//# sourceMappingURL=lesson.min.js.map.json\n';
  const map = JSON.parse(r.map);
  if (!map.sources || map.sources.length !== ORDER.length) {
    console.error('the map does not lead back to the ' + ORDER.length + ' sources (' + (map.sources || []).length + ')');
    process.exit(1);
  }
  map.file = 'lesson.min.js';
  delete map.sourcesContent;   // the sources are served beside it (see above)
  const mapText = JSON.stringify(map) + '\n';
  const hash = crypto.createHash('md5').update(code).digest('hex').slice(0, 8);
  return { code, mapText, hash };
}

const TAG = /(<script src="src\/lesson\.min\.js\?v=)([0-9a-f]+)(")/;

function run() {
  const { code, mapText, hash } = build();
  const page = fs.readFileSync(PAGE, 'utf8');
  const m = TAG.exec(page);
  if (!m) {
    console.error('index.html has no <script src="src/lesson.min.js?v=..."> to stamp');
    process.exit(1);
  }
  const stamped = page.replace(TAG, '$1' + hash + '$3');
  const have = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  const haveMap = fs.existsSync(MAP) ? fs.readFileSync(MAP, 'utf8') : '';
  const stale = [];
  if (have !== code) stale.push('src/lesson.min.js');
  if (haveMap !== mapText) stale.push('src/lesson.min.js.map.json');
  if (m[2] !== hash) stale.push('index.html (?v=' + m[2] + ', the bundle is ' + hash + ')');

  if (CHECK) {
    if (stale.length) {
      console.error('OUT OF DATE — run: node tools/build-bundle.js\n  ' + stale.join('\n  '));
      process.exit(1);
    }
    console.log('src/lesson.min.js is up to date: ' + ORDER.length + ' sources, ?v=' + hash);
    return;
  }
  if (have !== code) fs.writeFileSync(OUT, code);
  if (haveMap !== mapText) fs.writeFileSync(MAP, mapText);
  if (stamped !== page) fs.writeFileSync(PAGE, stamped);
  const raw = ORDER.reduce((a, f) => a + fs.statSync(path.join(ROOT, f)).size, 0);
  const kb = (n) => (n / 1024).toFixed(0) + ' KB';
  console.log('src/lesson.min.js: ' + ORDER.length + ' sources, ' + kb(raw) + ' -> ' + kb(Buffer.byteLength(code)) +
              ' (' + kb(zlib.gzipSync(code, { level: 9 }).length) + ' gzipped), ?v=' + hash +
              (stale.length ? '' : '  (unchanged)'));
}

run();

if (WATCH && !CHECK) {
  const names = new Set(ORDER.map((f) => path.basename(f)));
  let timer = null;
  console.log('watching src/ — Ctrl-C to stop');
  fs.watch(path.join(ROOT, 'src'), { recursive: true }, (ev, file) => {
    if (!file || !names.has(path.basename(String(file)))) return;
    clearTimeout(timer);
    timer = setTimeout(() => { try { run(); } catch (e) { console.error(e.message || e); } }, 150);
  });
}
